arguments.command:
sed -i '$d' tests/deliver_test.sh
cat >> tests/deliver_test.sh <<'EOF'
# ADR-0009: 4 attempts, waits 3/9/27 s; RELAY_ATTEMPTS raises the count (runbook "Slow endpoints").
[ "$(bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "plan default"; fail=1; }
[ "$(RELAY_ATTEMPTS=6 bash bin/deliver --plan)" = "attempts=6 waits=3,9,27,81,243" ] || { echo "plan RELAY_ATTEMPTS"; fail=1; }
[ "$(RELAY_RETRY_MAX=9 bash bin/deliver --plan)" = "attempts=4 waits=3,9,27" ] || { echo "RELAY_RETRY_MAX must be ignored"; fail=1; }
[ "$(RELAY_SLEEP=: bash bin/deliver false | grep -c '^attempt ')" = 4 ] || { echo "4 attempts"; fail=1; }
exit $fail
EOF
sed -i 's|^3 attempts with doubling.*|Superseded by ADR-0009: 4 attempts, waits 3^i s (3, 9, 27). The count can be raised with RELAY_ATTEMPTS for a slow partner.|; s|^- Partner B.s receiver takes long.*|- (Resolved in ADR-0009: 7 s was not enough; the budget is now 39 s.)|' docs/design/delivery.md
sed -i '0,/^## 3.4.1/s//## Unreleased\n\n- fix: deliver follows ADR-0009 again (4 attempts, waits 3\/9\/27 s) and reads `RELAY_ATTEMPTS` as the runbook says (RLY-731)\n\n## 3.4.1/' CHANGELOG.md
tail -8 tests/deliver_test.sh; git diff --stat; bash scripts/verify.sh
git stash -q -- lib; bash tests/deliver_test.sh; git stash pop -q

